    // no bus places this module: no protocol, only clk and the reset
    input  wire clk,
    input  wire rst_n,

    // Module ports
    output wire hsync,  // horizontal sync, low during the pulse (640x480@60)
    output wire vsync,  // vertical sync, low during the pulse
    output wire [11:0] rgb,  // the colour, red in the highest bits; black while blanked
    output wire pix_stb,  // one pulse per pixel clock (25 MHz): the cycle in which the outputs change
    output wire [9:0] x,  // the column of the source pixel to put on pixel, lead display pixels before the beam shows it
    output wire [8:0] y,  // its line
    output wire active,  // that pixel is inside the picture
    input  wire [11:0] pixel,  // the colour of the pixel at (x, y), on the wire lead pixels after x and y show it
    output wire vblank,  // high in vertical blanking, for the lead side
    output wire frame_start  // one cycle: the first cycle of pixel (0,0) on the lead side
);

    // The picture and the raster (640x480@60, both syncs low)
    // 640x480: 640 pixels a line, 480 lines, no RAM: the colour is the parent's wire, shown 1 x 1 times (50 MHz chip clock / 25 MHz = 2 cycles a pixel), lead 6 display pixels
    localparam SL     = 0;     // log2 of the scale
    localparam PHW    = 1;     // bits of the phase counter
    localparam [PHW-1:0] LASTPH = 1;  // the phase of the strobe cycle: cycles a pixel - 1
    localparam [9:0]  FX0   = 6;     // the lead counter starts this many display pixels ahead of the beam (lead:)
    localparam [9:0]  HA    = 640;   // active columns
    localparam [9:0]  HSS   = 656;   // first column of hsync
    localparam [9:0]  HSE   = 752;   // first column after hsync
    localparam [9:0]  HLAST = 799;   // last column: 800 samples a line
    localparam [9:0]  VA    = 480;   // active lines
    localparam [9:0]  VSS   = 490;   // first line of vsync
    localparam [9:0]  VSE   = 492;   // first line after vsync
    localparam [9:0]  VLAST = 524;   // last line: 525 lines a frame

    // Signals of the beam, the lead counter and the registered outputs
    logic [PHW-1:0]  ph;        // the cycle in the pixel
    logic            stb;       // the last cycle of a pixel: the outputs change at its end
    logic [9:0]      hx, vy;   // the beam: the pixel on show, column and line
    logic [9:0]      hx_n, vy_n;   // the next one
    logic [9:0]      fx, fy;   // the lead counter: the beam + lead display pixels
    logic [9:0]      fx_n, fy_n;   // the next one
    logic            hs_r, vs_r;   // the registered sync outputs
    logic            beam_active;  // the beam is inside the picture: the pixel on show is not black
    logic            vblank_r, frame_r;  // the registered vblank and frame_start of the lead side

    // The next column and line, of the pixel on show and of the fetch
    assign hx_n = (hx == HLAST) ? 10'd0 : hx + 10'd1;
    assign vy_n = (hx != HLAST) ? vy : (vy == VLAST) ? 10'd0 : vy + 10'd1;
    assign fx_n = (fx == HLAST) ? 10'd0 : fx + 10'd1;
    assign fy_n = (fx != HLAST) ? fy : (fy == VLAST) ? 10'd0 : fy + 10'd1;
    assign stb = (ph == LASTPH);

    // The beam: raster counters and sync outputs
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            ph <= {PHW{1'b0}};
            hx <= 10'd0;
            vy <= 10'd0;
            hs_r <= 1'b1;
            vs_r <= 1'b1;
        end else begin
            ph <= stb ? {PHW{1'b0}} : ph + 1'b1;
            if (stb) begin
                hx <= hx_n;
                vy <= vy_n;
                hs_r <= ~((hx_n >= HSS) && (hx_n < HSE));
                vs_r <= ~((vy_n >= VSS) && (vy_n < VSE));
            end
        end

    // The lead counter: the beam plus lead display pixels (none at lead 0)
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            fx <= FX0;
            fy <= 10'd0;
        end else if (stb) begin
            fx <= fx_n;
            fy <= fy_n;
        end

    // vblank and frame_start of the lead side, registered
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            vblank_r <= 1'b0;
            frame_r <= 1'b0;
        end else begin
            frame_r <= 1'b0;
            if (stb) begin
                vblank_r <= (fy_n >= VA);
                frame_r <= (fx_n == 10'd0) && (fy_n == 10'd0);
            end
        end

    // rgb: the parent's pixel inside the picture, black outside
    assign beam_active = (hx < HA) && (vy < VA);
    assign rgb = beam_active ? pixel : '0;

    // Outputs: hsync, vsync, rgb and the pixel strobe
    assign hsync = hs_r;
    assign vsync = vs_r;
    assign pix_stb = stb;

    // Outputs: x, y, active, vblank and frame_start of the lead side
    assign x = fx[9:SL];
    assign y = fy[8:SL];
    assign active = (fx < HA) && (fy < VA);
    assign vblank = vblank_r;
    assign frame_start = frame_r;

    // Bits nothing here reads, read on purpose
    wire _unused = &{1'b0, fy[9:9]};

endmodule
